# ! [doc = " This crate handles the user facing autodiff macro. For each `#[autodiff(...)]` attribute,"] # ! [doc = " we create an [`AutoDiffItem`] which contains the source and target function names. The source"] # ! [doc = " is the function to which the autodiff attribute is applied, and the target is the function"] # ! [doc = " getting generated by us (with a name given by the user as the first autodiff arg)."] use split_decls_genesis :: ourprelude :: * ; use std :: fmt :: { self , Display , Formatter } ; use std :: str :: FromStr ; use crate :: expand :: { Decodable , Encodable , HashStable_Generic } ; use crate :: { Ty , TyKind } ; #[doc = " Forward and Reverse Mode are well known names for automatic differentiation implementations."] #[doc = " Enzyme does support both, but with different semantics, see DiffActivity. The First variants"] #[doc = " are a hack to support higher order derivatives. We need to compute first order derivatives"] #[doc = " before we compute second order derivatives, otherwise we would differentiate our placeholder"] #[doc = " functions. The proper solution is to recognize and resolve this DAG of autodiff invocations,"] #[doc = " as it's already done in the C++ and Julia frontend of Enzyme."] #[doc = ""] #[doc = " Documentation for using [reverse](https://enzyme.mit.edu/rust/rev.html) and"] #[doc = " [forward](https://enzyme.mit.edu/rust/fwd.html) mode is available online."] #[derive (Clone , Copy , Eq , PartialEq , Encodable , Decodable , Debug , HashStable_Generic)] pub enum DiffMode { #[doc = " No autodiff is applied (used during error handling)."] Error , #[doc = " The primal function which we will differentiate."] Source , #[doc = " The target function, to be created using forward mode AD."] Forward , #[doc = " The target function, to be created using reverse mode AD."] Reverse , } #[doc = " Dual and Duplicated (and their Only variants) are getting lowered to the same Enzyme Activity."] #[doc = " However, under forward mode we overwrite the previous shadow value, while for reverse mode"] #[doc = " we add to the previous shadow value. To not surprise users, we picked different names."] #[doc = " Dual numbers is also a quite well known name for forward mode AD types."] #[derive (Clone , Copy , Eq , PartialEq , Encodable , Decodable , Debug , HashStable_Generic)] pub enum DiffActivity { #[doc = " Implicit or Explicit () return type, so a special case of Const."] None , #[doc = " Don't compute derivatives with respect to this input/output."] Const , #[doc = " Reverse Mode, Compute derivatives for this scalar input/output."] Active , #[doc = " Reverse Mode, Compute derivatives for this scalar output, but don't compute"] #[doc = " the original return value."] ActiveOnly , #[doc = " Forward Mode, Compute derivatives for this input/output and *overwrite* the shadow argument"] #[doc = " with it."] Dual , #[doc = " Forward Mode, Compute derivatives for this input/output and *overwrite* the shadow argument"] #[doc = " with it. It expects the shadow argument to be `width` times larger than the original"] #[doc = " input/output."] Dualv , #[doc = " Forward Mode, Compute derivatives for this input/output and *overwrite* the shadow argument"] #[doc = " with it. Drop the code which updates the original input/output for maximum performance."] DualOnly , #[doc = " Forward Mode, Compute derivatives for this input/output and *overwrite* the shadow argument"] #[doc = " with it. Drop the code which updates the original input/output for maximum performance."] #[doc = " It expects the shadow argument to be `width` times larger than the original input/output."] DualvOnly , #[doc = " Reverse Mode, Compute derivatives for this &T or *T input and *add* it to the shadow argument."] Duplicated , #[doc = " Reverse Mode, Compute derivatives for this &T or *T input and *add* it to the shadow argument."] #[doc = " Drop the code which updates the original input for maximum performance."] DuplicatedOnly , #[doc = " All Integers must be Const, but these are used to mark the integer which represents the"] #[doc = " length of a slice/vec. This is used for safety checks on slices."] #[doc = " The integer (if given) specifies the size of the slice element in bytes."] FakeActivitySize (Option < u32 >) , } impl DiffActivity { pub fn is_dual_or_const (& self) -> bool { use DiffActivity :: * ; matches ! (self , | Dual | DualOnly | Dualv | DualvOnly | Const) } } #[doc = " We generate one of these structs for each `#[autodiff(...)]` attribute."] #[derive (Clone , Eq , PartialEq , Encodable , Decodable , Debug , HashStable_Generic)] pub struct AutoDiffItem { #[doc = " The name of the function getting differentiated"] pub source : String , #[doc = " The name of the function being generated"] pub target : String , pub attrs : AutoDiffAttrs , } #[derive (Clone , Eq , PartialEq , Encodable , Decodable , Debug , HashStable_Generic)] pub struct AutoDiffAttrs { #[doc = " Conceptually either forward or reverse mode AD, as described in various autodiff papers and"] #[doc = " e.g. in the [JAX"] #[doc = " Documentation](https://jax.readthedocs.io/en/latest/_tutorials/advanced-autodiff.html#how-it-s-made-two-foundational-autodiff-functions)."] pub mode : DiffMode , #[doc = " A user-provided, batching width. If not given, we will default to 1 (no batching)."] #[doc = " Calling a differentiated, non-batched function through a loop 100 times is equivalent to:"] #[doc = " - Calling the function 50 times with a batch size of 2"] #[doc = " - Calling the function 25 times with a batch size of 4,"] #[doc = " etc. A batched function takes more (or longer) arguments, and might be able to benefit from"] #[doc = " cache locality, better re-usal of primal values, and other optimizations."] #[doc = " We will (before LLVM's vectorizer runs) just generate most LLVM-IR instructions `width`"] #[doc = " times, so this massively increases code size. As such, values like 1024 are unlikely to"] #[doc = " work. We should consider limiting this to u8 or u16, but will leave it at u32 for"] #[doc = " experiments for now and focus on documenting the implications of a large width."] pub width : u32 , pub ret_activity : DiffActivity , pub input_activity : Vec < DiffActivity > , } impl AutoDiffAttrs { pub fn has_primal_ret (& self) -> bool { matches ! (self . ret_activity , DiffActivity :: Active | DiffActivity :: Dual) } } impl DiffMode { pub fn is_rev (& self) -> bool { matches ! (self , DiffMode :: Reverse) } pub fn is_fwd (& self) -> bool { matches ! (self , DiffMode :: Forward) } } impl Display for DiffMode { fn fmt (& self , f : & mut Formatter < '_ >) -> fmt :: Result { match self { DiffMode :: Error => write ! (f , "Error") , DiffMode :: Source => write ! (f , "Source") , DiffMode :: Forward => write ! (f , "Forward") , DiffMode :: Reverse => write ! (f , "Reverse") , } } } #[doc = " Active(Only) is valid in reverse-mode AD for scalar float returns (f16/f32/...)."] #[doc = " Dual(Only) is valid in forward-mode AD for scalar float returns (f16/f32/...)."] #[doc = " Const is valid for all cases and means that we don't compute derivatives wrt. this output."] #[doc = " That usually means we have a &mut or *mut T output and compute derivatives wrt. that arg,"] #[doc = " but this is too complex to verify here. Also it's just a logic error if users get this wrong."] pub fn valid_ret_activity (mode : DiffMode , activity : DiffActivity) -> bool { if activity == DiffActivity :: None { return true ; } match mode { DiffMode :: Error => false , DiffMode :: Source => false , DiffMode :: Forward => activity . is_dual_or_const () , DiffMode :: Reverse => { activity == DiffActivity :: Const || activity == DiffActivity :: Active || activity == DiffActivity :: ActiveOnly } } } #[doc = " For indirections (ptr/ref) we can't use Active, since Active allocates a shadow value"] #[doc = " for the given argument, but we generally can't know the size of such a type."] #[doc = " For scalar types (f16/f32/f64/f128) we can use Active and we can't use Duplicated,"] #[doc = " since Duplicated expects a mutable ref/ptr and we would thus end up with a shadow value"] #[doc = " who is an indirect type, which doesn't match the primal scalar type. We can't prevent"] #[doc = " users here from marking scalars as Duplicated, due to type aliases."] pub fn valid_ty_for_activity (ty : & Box < Ty > , activity : DiffActivity) -> bool { use DiffActivity :: * ; if activity . is_dual_or_const () { return true ; } if matches ! (activity , Active | ActiveOnly) { return true ; } matches ! (ty . kind , TyKind :: Ptr (_) | TyKind :: Ref (..)) && matches ! (activity , Duplicated | DuplicatedOnly) } pub fn valid_input_activity (mode : DiffMode , activity : DiffActivity) -> bool { use DiffActivity :: * ; return match mode { DiffMode :: Error => false , DiffMode :: Source => false , DiffMode :: Forward => activity . is_dual_or_const () , DiffMode :: Reverse => { matches ! (activity , Active | ActiveOnly | Duplicated | DuplicatedOnly | Const) } } ; } impl Display for DiffActivity { fn fmt (& self , f : & mut Formatter < '_ >) -> std :: fmt :: Result { match self { DiffActivity :: None => write ! (f , "None") , DiffActivity :: Const => write ! (f , "Const") , DiffActivity :: Active => write ! (f , "Active") , DiffActivity :: ActiveOnly => write ! (f , "ActiveOnly") , DiffActivity :: Dual => write ! (f , "Dual") , DiffActivity :: Dualv => write ! (f , "Dualv") , DiffActivity :: DualOnly => write ! (f , "DualOnly") , DiffActivity :: DualvOnly => write ! (f , "DualvOnly") , DiffActivity :: Duplicated => write ! (f , "Duplicated") , DiffActivity :: DuplicatedOnly => write ! (f , "DuplicatedOnly") , DiffActivity :: FakeActivitySize (s) => write ! (f , "FakeActivitySize({:?})" , s) , } } } impl FromStr for DiffMode { type Err = () ; fn from_str (s : & str) -> Result < DiffMode , () > { match s { "Error" => Ok (DiffMode :: Error) , "Source" => Ok (DiffMode :: Source) , "Forward" => Ok (DiffMode :: Forward) , "Reverse" => Ok (DiffMode :: Reverse) , _ => Err (()) , } } } impl FromStr for DiffActivity { type Err = () ; fn from_str (s : & str) -> Result < DiffActivity , () > { match s { "None" => Ok (DiffActivity :: None) , "Active" => Ok (DiffActivity :: Active) , "ActiveOnly" => Ok (DiffActivity :: ActiveOnly) , "Const" => Ok (DiffActivity :: Const) , "Dual" => Ok (DiffActivity :: Dual) , "Dualv" => Ok (DiffActivity :: Dualv) , "DualOnly" => Ok (DiffActivity :: DualOnly) , "DualvOnly" => Ok (DiffActivity :: DualvOnly) , "Duplicated" => Ok (DiffActivity :: Duplicated) , "DuplicatedOnly" => Ok (DiffActivity :: DuplicatedOnly) , _ => Err (()) , } } } impl AutoDiffAttrs { pub fn has_ret_activity (& self) -> bool { self . ret_activity != DiffActivity :: None } pub fn has_active_only_ret (& self) -> bool { self . ret_activity == DiffActivity :: ActiveOnly } pub const fn error () -> Self { AutoDiffAttrs { mode : DiffMode :: Error , width : 0 , ret_activity : DiffActivity :: None , input_activity : Vec :: new () , } } pub fn source () -> Self { AutoDiffAttrs { mode : DiffMode :: Source , width : 0 , ret_activity : DiffActivity :: None , input_activity : Vec :: new () , } } pub fn is_active (& self) -> bool { self . mode != DiffMode :: Error } pub fn is_source (& self) -> bool { self . mode == DiffMode :: Source } pub fn apply_autodiff (& self) -> bool { ! matches ! (self . mode , DiffMode :: Error | DiffMode :: Source) } pub fn into_item (self , source : String , target : String) -> AutoDiffItem { AutoDiffItem { source , target , attrs : self } } } impl fmt :: Display for AutoDiffItem { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { write ! (f , "Differentiating {} -> {}" , self . source , self . target) ? ; write ! (f , " with attributes: {:?}" , self . attrs) } }